/// <summary>
/// PricingAttribute of table <c>CustTable</c> field PaymTermId.
/// </summary>
[GUPPricingMetadataDiscovery][GUPPricingAttributeSourceDiscovery(GUPPricingAttributeSource::Customer, GUPPricingAttributeSourceLevel::Header)]
[GUPPricingAttributeFieldsDiscovery(fieldStr(CustTable, PaymTermId))]
internal class GUPPricingAttributeCustTablePaymTermId extends GUPPricingAttributeCustTable implements GUPIPricingAttribute
{
}

Method.Source:
public str getName()
{
    return fieldPName(CustTable, PaymTermId);
}

public Set getAllowedValuesWithDescription()
{
    var ret = new Set(Types::AnyType);

    CustTable custTable;
    PaymTerm  paymTerm;

    while select PaymTermId from custtable
        join paymTerm 
        group by PaymTermId, Description
        where custTable.PaymTermId == paymTerm.PaymTermId                                 
    {
        GUPPricingAttributeAllowedValuesObject valueObject =
            new GUPPricingAttributeAllowedValuesObject(paymTerm.paymTermId, paymTerm.Description);
        ret.add(valueObject);
    }
    return ret;
}
